/*
 * ext/dom's HTML5 glue around lexbor: the parsing pipeline (encoding
 * sniffing and decoding, chunked parsing, error reports), the conversion of
 * lexbor's tree to libxml2's, and the output encoding of saveHtml().
 * Generated by gen.py from php-src 8.5.12's ext/dom/html_document.c,
 * html5_parser.c and html5_parser.h (PHP License 3.01): php's code, with
 * its Zend calls replaced by the rhp_dom_* callbacks (ext/dom/html5.rs),
 * then head.c's definitions before it and tail.c's API after it.
 */
/* vasprintf/asprintf on glibc */
#define _GNU_SOURCE
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
